css:
.ratio-dispatch-slip { border: 1px solid #777; font-size: 12px; }
.ratio-dispatch-slip .header { display: flex; border-bottom: 1px solid #777; }
.ratio-dispatch-slip .party { width: 34%; padding: 7px; }
.ratio-dispatch-slip .document { width: 32%; border-left: 1px solid #aaa; padding: 7px; }
.ratio-dispatch-slip .title { font-size: 16px; font-weight: 700; text-align: center; margin-bottom: 5px; }
.ratio-dispatch-slip .group-title { margin: 10px 0 4px; font-weight: 700; }
.ratio-dispatch-slip table { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.ratio-dispatch-slip th, .ratio-dispatch-slip td { border: 1px solid #aaa; padding: 5px 7px; }
.ratio-dispatch-slip th { background: #f3f4f6; }
.ratio-dispatch-slip .number { text-align: center; }
.ratio-dispatch-slip .footer-row { border-top: 1px solid #777; padding: 7px; }
.ratio-dispatch-slip .signatures { display: flex; border-top: 1px solid #777; min-height: 85px; }
.ratio-dispatch-slip .signature { width: 50%; padding: 8px; text-align: center; }
.ratio-dispatch-slip .signature + .signature { border-left: 1px solid #777; }
#ratio-print-watermark { position: fixed; top: 40%; left: 12%; z-index: 1; font-size: 110px; color: #aaa; opacity: .25; transform: rotate(-45deg); }

html:
{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
{% set groups = get_ratio_dispatch_print_data(doc.name) %}
<div class="ratio-dispatch-slip">
    {% if doc.docstatus == 0 %}<div id="ratio-print-watermark">DRAFT</div>{% elif doc.docstatus == 2 %}<div id="ratio-print-watermark">CANCELLED</div>{% endif %}
    {% set from_supplier = doc.from_warehouse %}
    {% set to_supplier = doc.to_warehouse or doc.transfer_supplier %}
    <div class="header">
        <div class="party">
            <small>From:</small><br>
            {% if from_supplier %}
                <strong>{{ frappe.db.get_value("Supplier", from_supplier, "supplier_name") or from_supplier }}</strong>
                {% set from_address = get_supplier_address_display(from_supplier) %}
                {% if from_address %}<br>{{ from_address }}{% endif %}
            {% else %}&mdash;{% endif %}
        </div>
        <div class="party">
            <small>To:</small><br>
            {% if to_supplier %}
                <strong>{{ frappe.db.get_value("Supplier", to_supplier, "supplier_name") or to_supplier }}</strong>
                {% set to_address = get_supplier_address_display(to_supplier) %}
                {% if to_address %}<br>{{ to_address }}{% endif %}
            {% else %}&mdash;{% endif %}
        </div>
        <div class="document">
            <div class="title">Ratio Dispatch Colour Slip</div>
            <div><small>Date:</small> <strong>{{ doc.get_formatted("posting_date") }}</strong></div>
            <div><small>No.:</small> <strong>{{ doc.name }}</strong></div>
            {% if doc.vehicle_no %}<div><small>Vehicle No:</small> <strong>{{ doc.vehicle_no }}</strong></div>{% endif %}
        </div>
    </div>
    <div style="padding: 7px;">
        {% if groups %}
            {% for group in groups %}
                <div class="group-title">Lot: {{ group.lot }} &nbsp;&nbsp; Item: {{ group.item }} &nbsp;&nbsp; Finishing Plan: {{ group.finishing_plan }}</div>
                <table>
                    <thead><tr><th class="number" style="width: 55px;">S.No.</th><th>Colour</th><th class="number" style="width: 130px;">Boxes</th></tr></thead>
                    <tbody>
                        {% for row in group.colours %}
                            <tr><td class="number">{{ loop.index }}</td><td>{{ row.colour }}</td><td class="number"><strong>{{ row.boxes | round(2) }}</strong></td></tr>
                        {% endfor %}
                        <tr><td colspan="2"><strong>Total</strong></td><td class="number"><strong>{{ group.total_boxes | round(2) }}</strong></td></tr>
                    </tbody>
                </table>
            {% endfor %}
        {% else %}
            <div style="padding: 18px; text-align: center;">No ratio-packed colour-wise box data is available for this Stock Entry.</div>
        {% endif %}
    </div>
    {% if doc.comments %}<div class="footer-row"><strong>Comments:</strong> {{ doc.comments }}</div>{% endif %}
    {% if doc.terms_and_condition %}
        {% set terms = frappe.get_all("Terms and Condition Detail", filters={"parent": doc.terms_and_condition, "parenttype": "Terms and Condition"}, fields=["term"], order_by="idx asc") %}
        {% if terms %}<div class="footer-row"><strong>Terms and Conditions:</strong><ol>{% for term in terms %}<li>{{ term.term }}</li>{% endfor %}</ol></div>{% endif %}
    {% endif %}
    <div class="signatures">
        <div class="signature">Receiver's Signature<br><br><br>Name: ____________________</div>
        <div class="signature">For <strong>{{ frappe.db.get_single_value("Company Settings", "company") or "" }}</strong><br><br><br>Authorized Signatory</div>
    </div>
</div>
{% if footer and not no_letterhead %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}
